function longestRising(ids: number[]): number {
  // tops[k] = smallest last id of any rising chain of length k + 1 seen so far.
  const tops: number[] = [];
  for (const id of ids) {
    let lo = 0, hi = tops.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tops[mid] < id) lo = mid + 1;
      else hi = mid;
    }
    tops[lo] = id;
  }
  return tops.length;
}
